import json, sys
from concurrent.futures import ThreadPoolExecutor
from lib import *
P = {
 "seasons": {"persona": "Марина, 34 года, бухгалтер, школьную физику почти не помнит. Знает, что Земля вращается вокруг Солнца и вокруг своей оси. Заблуждение: зима бывает потому, что Земля дальше от Солнца. Про наклон оси слышала, но не понимает, при чём он. Не знает, что в Австралии сезоны наоборот.",
  "probes": ["Привет! Для начала угадай: почему летом жарче, чем зимой?",
   "А что такое перигелий и в каком месяце Земля к нему ближе всего?",
   "Смотри: ось Земли наклонена на 23,4° и сохраняет направление в пространстве; поэтому полушарие, обращённое к Солнцу, получает лучи под более прямым углом; энергия на квадратный метр зависит от косинуса угла падения; плюс долгота дня больше; при этом расстояние меняется всего на 3% и в январе Земля даже ближе; поэтому в Южном полушарии сезоны противоположны; а на экваторе выраженных сезонов почти нет. Понятно?",
   "Короче: летом наше полушарие наклонено к Солнцу, лучи падают круче и день длиннее, поэтому теплее. Расстояние почти не влияет. Тогда вопрос: какое время года в Сиднее в январе и почему?",
   "Представь планету без наклона оси, но с очень вытянутой орбитой. Будут ли там сезоны и одинаковые ли во всех полушариях?"]},
 "range": {"persona": "Тимур, 16 лет, школьник, любит футбол, программирует первый месяц: знает print, переменные, if. Циклы видел мельком. Заблуждение: range(5) даёт числа от 1 до 5. Путает = и ==. Не знает, что такое итерация.",
  "probes": ["Привет! Что выведет этот код, как думаешь?\nfor i in range(3):\n    print(i)",
   "А что такое генератор и чем он отличается от списка?",
   "Смотри: range(n) создаёт ленивую последовательность от 0 до n-1; for берёт из неё элементы по одному (это итерация); переменная цикла перезаписывается на каждом шаге; тело цикла выделяется отступом в 4 пробела; range можно задать как range(start, stop, step); stop не включается; а ещё есть break и continue. Понятно?",
   "Короче: range(3) — это 0, 1, 2. Начинается с нуля, последнее число не включается. Тогда что выведет:\nfor i in range(2, 5):\n    print(i * 10)",
   "Напиши цикл, который печатает номера игроков от 1 до 11 включительно."]}}
def run(name, model):
    p = P[name]; sys_ = LEARNER_RULES.format(persona=p["persona"]); sess=None; out=[]; cost=0
    for pr in p["probes"]:
        t, sess, c, _ = claude("Репетитор: " + pr, model, system=sys_, session=sess); cost += c
        out.append({"tutor": pr, "learner": t})
    return {"persona": name, "model": model, "cost": cost, "turns": out}
jobs = [(n, m) for n in P for m in ["claude-sonnet-5-5", "claude-opus-5-5"]]
with ThreadPoolExecutor(4) as ex: res = list(ex.map(lambda a: run(*a), jobs))
json.dump(res, open("calib_raw.json", "w"), ensure_ascii=False, indent=1)
print(sum(r["cost"] for r in res))
